module legacy_trait_names;
pub struct Self<T> { value:T; }
fn trait<T>(value:T)->T { return value; }
fn impl(value:Self<str>)->str { return trait(value.value); }
fn type(value:i64)->i64 { return value+1; }
fn for(value:i64)->i64 { return type(value); }
fn keep<Self>(value:Self)->Self { return value; }
fn main()->unit!{io} {
  let apply:fn(i64)->i64=for;
  print(impl(Self<str>("Я\u0000🧠")));
  print(apply(keep(41)));
}
test fn preserved_names()->unit {
  assert(impl(Self<str>("Я\u0000🧠"))=="Я\u0000🧠");
  let apply:fn(i64)->i64=for;
  assert(apply(keep(41))==42);
}
